#include <bits/stdc++.h>
#include <ext/pb_ds/assoc_container.hpp>
#include <ext/pb_ds/tree_policy.hpp>

using namespace std;
using namespace __gnu_pbds;

using Key = tuple<long long, long long, int>;
using OrderedTree = tree<Key, null_type, less<Key>, rb_tree_tag,
                         tree_order_statistics_node_update>;

class Solver {
    int n;
    long long k;
    vector<long long> height, u, v;
    vector<int> parent;
    vector<char> active;
    vector<vector<int>> members;
    vector<unique_ptr<OrderedTree>> treeU, treeV;
    long long total = 0;

    int findRoot(int x) {
        if (parent[x] != x) parent[x] = findRoot(parent[x]);
        return parent[x];
    }

    static long long rankOf(const OrderedTree& tr, long long x,
                            long long h, int idx) {
        return static_cast<long long>(
            tr.order_of_key(Key{x, h, idx})
        );
    }

    long long countRightForLeft(int p, int root) const {
        const auto& tu = *treeU[root];
        const auto& tv = *treeV[root];

        long long uTarget = u[p] + k;
        long long vTarget = v[p] + k;

        long long first =
            rankOf(tu, uTarget + 1, LLONG_MIN, INT_MIN) -
            rankOf(tu, uTarget, height[p], INT_MIN);

        long long second =
            rankOf(tv, vTarget, height[p], INT_MIN) -
            rankOf(tv, vTarget, LLONG_MIN, INT_MIN);

        return first + second;
    }

    long long countLeftForRight(int p, int root) const {
        const auto& tu = *treeU[root];
        const auto& tv = *treeV[root];

        long long uTarget = u[p] - k;
        long long vTarget = v[p] - k;

        long long first =
            rankOf(tu, uTarget, height[p], INT_MAX) -
            rankOf(tu, uTarget, LLONG_MIN, INT_MIN);

        long long second =
            rankOf(tv, vTarget + 1, LLONG_MIN, INT_MIN) -
            rankOf(tv, vTarget, height[p], INT_MAX);

        return first + second;
    }

    void activate(int x) {
        active[x] = true;
        parent[x] = x;
        members[x].push_back(x);

        treeU[x] = make_unique<OrderedTree>();
        treeV[x] = make_unique<OrderedTree>();
        treeU[x]->insert(Key{u[x], height[x], x});
        treeV[x]->insert(Key{v[x], height[x], x});
    }

    int mergeComponents(int leftRoot, int rightRoot) {
        int l = findRoot(leftRoot);
        int r = findRoot(rightRoot);
        if (l == r) return l;

        bool leftIsSmall = members[l].size() <= members[r].size();
        int small = leftIsSmall ? l : r;
        int large = leftIsSmall ? r : l;

        if (leftIsSmall) {
            for (int p : members[small])
                total += countRightForLeft(p, large);
        } else {
            for (int p : members[small])
                total += countLeftForRight(p, large);
        }

        for (int p : members[small]) {
            treeU[large]->insert(Key{u[p], height[p], p});
            treeV[large]->insert(Key{v[p], height[p], p});
        }

        members[large].insert(members[large].end(),
                              members[small].begin(),
                              members[small].end());
        members[small].clear();

        treeU[small].reset();
        treeV[small].reset();
        parent[small] = large;

        return large;
    }

public:
    Solver(int n_, long long k_) : n(n_), k(k_) {}

    void run() {
        height.resize(n);
        u.resize(n);
        v.resize(n);
        parent.resize(n);
        active.assign(n, false);
        members.resize(n);
        treeU.resize(n);
        treeV.resize(n);

        for (int i = 0; i < n; ++i) {
            cin >> height[i];
            u[i] = (i + 1LL) + height[i];
            v[i] = (i + 1LL) - height[i];
        }

        int q;
        cin >> q;
    }
};

