    }

    vector<long long> answer(q + 1);
    answer[q] = total;

    for (int t = q - 1; t >= 0; --t) {
        int x = destroyed[t];
        activate(x);

        if (x > 0 && active[x - 1])
            mergeComponents(x - 1, x);
        if (x + 1 < n && active[x + 1])
            mergeComponents(x, x + 1);

        answer[t] = total;
    }

    for (long long x : answer) cout << x << '\n';
    return 0;
}
